  t["Olvidar el $+ 360^\\circ k$"] = "Forgetting the $+ 360^\\circ k$";
  t["Olvidar el $+C$"] = "Forgetting the $+C$";
  t["Olvidar el caso base."] = "Forgetting the base case.";
  t["Olvidar el caso general"] = "Forgetting the general case";
  t["Olvidar el coeficiente que falta"] = "Forgetting the missing coefficient";
  t["Olvidar el número combinatorio"] = "Forgetting the binomial coefficient";
  t["Olvidar el signo menos de la segunda componente de $\\vec u\\times\\vec v$"] = "Forgetting the minus sign on the second component of $\\vec u\\times\\vec v$";
  t["Olvidar el tercio en pirámides y conos"] = "Forgetting the third in pyramids and cones";
  t["Olvidar la columna de la derecha"] = "Forgetting the right-hand column";
  t["Olvidar la lista"] = "Forgetting the list";
