  t["}$<br><span style=\"font-size:0.875rem;color:var(--ink-faint)\">Si es infinito, escribe <code>inf</code> o <code>-inf</code>.</span>"] = "}$<br><span style=\"font-size:0.875rem;color:var(--ink-faint)\">If it is infinite, write <code>inf</code> or <code>-inf</code>.</span>";
