  t["¿Cuál es el vector normal del plano $2x - y + 3z - 6 = 0$?"] = "What is the normal vector of the plane $2x - y + 3z - 6 = 0$?";
  t["¿Cuál es la abscisa del vértice de $f(x) = x^2 - 6x + 5$?"] = "What is the x-coordinate of the vertex of $f(x) = x^2 - 6x + 5$?";
