  t["¿Cuál es la negación de «<em>"] = "What is the negation of “<em>";
  t["¿Cuál es la negación de «he aprobado matemáticas <strong>y</strong> he aprobado física»?"] = "What is the negation of “I passed maths <strong>and</strong> I passed physics”?";
  t["¿Cuál es la probabilidad de que haga deporte y duerma más de 8 horas? (Vale una fracción.)"] = "What is the probability that they do sport and sleep more than 8 hours? (A fraction is fine.)";
  t["¿Cuál es la probabilidad de que una persona mida <strong>exactamente</strong> 1,75 m? No 1,7501 ni 1,74999: exactamente 1,750000… con infinitos ceros."] = "What is the probability that a person is <strong>exactly</strong> 1.75 m tall? Not 1.7501 nor 1.74999: exactly 1.750000… with infinitely many zeros.";
  t["¿Cuál es la solución de $x^2 - 9 > 0$?"] = "What is the solution of $x^2 - 9 > 0$?";
  t["¿Cuál es mayor, $9\\,876$ o $10\\,234$?"] = "Which is larger, $9{,}876$ or $10{,}234$?";
